/* ═══════════════════════ 3) İADE VE SEPET ANALİZİ ═══════════════════════ */
const IX = { 'Satır': 'COUNTROWS(Satislar)', 'İade Satırı': 'CALCULATE(COUNTROWS(Satislar), Satislar[Durum] = "İade")', 'Ürün Çeşidi': 'DISTINCTCOUNT(Satislar[UrunNo])', 'İade Oranı GY': 'CALCULATE([İade Oranı %], SAMEPERIODLASTYEAR(Tarih[Tarih]))' };
const IF_ = { 'İade Oranı %': 'yuzde', 'İade Tutarı': 'para' };
const im = a => a.prm('iolcu') || 'İade Oranı %'; const ifm = a => IF_[im(a)] || 'yuzde';
const iq = (a, rows, vals, o) => a.Q(rows, vals, Object.assign({ extraMeasures: IX }, o || {}));
const TK = [{ t: 'Talepler', c: 'Konu', values: ['İade ve değişim'] }];
function basket(a, o) {
  return memo(skey(a, 'bsk', o), () => {
    const r = a.Q(['Satislar[SiparisNo]', 'Satislar[UrunNo]'], ['Satılan Adet'], Object.assign({ totals: false }, o || {}));
    const ord = new Map(); r.rows.forEach(x => { if (!x.vals[0]) return; const k = x.keys[0]; if (!ord.has(k)) ord.set(k, new Set()); ord.get(k).add(x.keys[1]); });
    const n = ord.size, cnt = {}, pair = {};
    ord.forEach(s => { const u = [...s].sort((p, q) => p - q); u.forEach(p => { cnt[p] = (cnt[p] || 0) + 1; }); for (let i = 0; i < u.length; i++) for (let j = i + 1; j < u.length; j++) { const k = u[i] + '-' + u[j]; pair[k] = (pair[k] || 0) + 1; } });
    const pairs = Object.keys(pair).map(k => { const [p, q] = k.split('-').map(Number); const c = pair[k]; return { a: p, b: q, n: c, sup: c / n, confAB: c / cnt[p], confBA: c / cnt[q], lift: (c / n) / ((cnt[p] / n) * (cnt[q] / n)) }; });
    const sizes = [...ord.values()].map(s => s.size);
    return { n, cnt, pairs, ord, multi: sizes.filter(s => s > 1).length, avg: n ? sum(sizes) / n : null };
  });
}
const itip = (a, add, cat) => {
  const o = { add, extraMeasures: IX }; const p = sortBy(a.Q(['Urunler[Urun]'], ['İade Tutarı'], { add, totals: false }), 0).rows.filter(x => x.vals[0]); const r = iq(a, [a.timeAxis], ['İade Oranı %'], { add, totals: false });
  return { title: 'Araç ipucu · ' + cat, cards: [['İade oranı', a.fmt(a.M('[İade Oranı %]', o), 'yuzde')], ['İade tutarı', a.fmt(a.M('[İade Tutarı]', o), 'para', true)], ['İade satırı', a.fmt(a.M('[İade Satırı]', o), 'adet')], ['Ort. indirim', a.fmt(a.M('[Ortalama İndirim %]', o), 'yuzde')]], bars: p.slice(0, 4).map(x => [x.keys[0], x.vals[0], a.fmt(x.vals[0], 'para', true)]), barsLabel: 'En çok iade edilen ürünler (₺)', spark: col(r, 0), sparkLabel: 'Aylık iade oranı' };
};
const inav = (n, sp) => nav('inav' + n, [{ label: 'Genel bakış', icon: '◉', page: 'genel' }, { label: 'İade nedenleri', icon: '⚑', page: 'neden' }, { label: 'Sepet analizi', icon: '⧉', page: 'sepet' }, { label: 'İade talepleri', icon: '☏', page: 'destek' }], sp || 8);
